command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="9b468483d7dc259564a142396d7ee29f123ede73"
$branch="work/shell-provider-copyout-20261007"
Set-Location -LiteralPath $repo
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch failed"}
$observed=(& git rev-parse refs/remotes/origin/main).Trim()
if($observed -ne $main){throw "main changed"}
$ref="refs/remotes/origin/"+$branch
& git show-ref --verify --quiet $ref
if($LASTEXITCODE -ne 0){throw "work branch missing"}
$branchHead=(& git rev-parse $ref).Trim()
if($branchHead -ne $main){throw "work branch differs from main"}
& git merge-base --is-ancestor $branchHead $observed
if($LASTEXITCODE -ne 0){throw "work branch not merged"}
& git push origin --delete $branch
if($LASTEXITCODE -ne 0){throw "branch delete failed"}
& git fetch origin --no-tags --prune
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
& git show-ref --verify --quiet $ref
if($LASTEXITCODE -eq 0){throw "branch remains"}
Write-Host "SHELL_PROVIDER_COPYOUT_WORK_BRANCH_CLEANUP=PASS"
